43: 
44: const MarkPatientDeceasedForm: React.FC<PatientWorkspace2DefinitionProps<{}, {}>> = ({
45:   closeWorkspace,
46:   groupProps: { patientUuid, patient },
47: }) => {
48:   const { t } = useTranslation();
49:   const isTablet = useLayoutType() === 'tablet';
50:   const memoizedState = useMemo(() => ({ patientUuid, patient }), [patientUuid, patient]);
51:   const [searchTerm, setSearchTerm] = useState('');
52:   const { causesOfDeath, isLoading: isLoadingCausesOfDeath } = useCausesOfDeath();
53:   const { freeTextFieldConceptUuid } = useConfig<ChartConfig>();
54:   const { mutate: globalMutate } = useSWRConfig();
55:   const patientBirthDate = useMemo(() => (patient?.birthDate ? parseDate(patient.birthDate) : undefined), [patient]);
56: 
57:   const filteredCausesOfDeath = useMemo(() => {
58:     if (!searchTerm) {
59:       return causesOfDeath;
60:     }
61:     return searchTerm
62:       ? fuzzy
63:           .filter(searchTerm, causesOfDeath, {
64:             extract: (causeOfDeathConcept) => causeOfDeathConcept.display,
65:           })
66:           .sort((r1, r2) => r1.score - r2.score)
67:           .map((result) => result.original)
68:       : causesOfDeath;
69:   }, [searchTerm, causesOfDeath]);
70: 
71:   const handleSearchTermChange = (event) => {
72:     setSearchTerm(event.target.value);
73:   };
74: 
75:   const schema = z
76:     .object({
77:       causeOfDeath: z.string().refine((causeOfDeath) => !!causeOfDeath, {
78:         message: t('causeOfDeathIsRequired', 'Please select the cause of death'),
79:       }),
80:       deathDate: z
81:         .date()
82:         .refine((date) => !!date, {
83:           message: t('deathDateRequired', 'Please select the date of death'),
84:         })
85:         .refine((date) => !patientBirthDate || date >= patientBirthDate, {
86:           message: t('deathDateBeforeBirthDate', 'Death date cannot be before the date of birth'),
87:         }),
88:       nonCodedCauseOfDeath: z.string().optional(),
89:     })
90:     .refine((data) => !(data.causeOfDeath === freeTextFieldConceptUuid && !data.nonCodedCauseOfDeath), {
91:       message: t('nonCodedCauseOfDeathRequired', 'Please enter the non-coded cause of death'),
92:       path: ['nonCodedCauseOfDeath'],
93:     });
94: 
95:   type MarkPatientDeceasedFormSchema = z.infer<typeof schema>;
96: 
97:   const {
98:     control,
99:     formState: { errors, isSubmitting, isDirty },
100:     handleSubmit,
101:     watch,
102:   } = useForm<MarkPatientDeceasedFormSchema>({
103:     mode: 'onSubmit',
