134:             subtitle: error?.message,
135:             title: t('errorMarkingPatientDeceased', 'Error marking patient deceased'),
136:           });
137:         });
138:     },
139:     [closeWorkspace, globalMutate, patientUuid, t],
140:   );
141: 
142:   const onError = (errors) => console.error(errors);
143: 
144:   return (
145:     <Workspace2 title={t('markPatientDeceased', 'Mark patient deceased')} hasUnsavedChanges={isDirty}>
146:       <Form className={styles.form} onSubmit={handleSubmit(onSubmit, onError)}>
147:         <div>
